/** static void TipAndShake_2(struct Sprite *sprite) */
export function TipAndShake_2(sprite: any): any {
  TryFlipX(sprite);
      sprite.data[7] += (sprite.data[6] * 4);
      if (sprite.data[5] > 9)
      {
          sprite.data[7] = 32;
          sprite.callback = TipAndShake_3;
      }

      sprite.x2 = Sin(sprite.data[7], 8);
      sprite.y2 = -(Sin(sprite.data[7], 8));
      if (sprite.data[7] <= 28 || sprite.data[7] >= 36)
      {
          sprite.data[6] *= -1;
          sprite.data[5]++;
      }

      HandleSetAffineData(sprite, 256, 256, -(sprite.data[7]) << 8);
      TryFlipX(sprite);
}

/** static void TipAndShake_3(struct Sprite *sprite) */
export function TipAndShake_3(sprite: any): any {
  TryFlipX(sprite);
      if (sprite.data[7] <= 0)
      {
          sprite.data[7] = 0;
          ResetSpriteAfterAnim(sprite);
          sprite.callback = WaitAnimEnd;
      }
      else
      {
          sprite.data[7] -= 2;
          sprite.x2 = Sin(sprite.data[7], 8);
          sprite.y2 = -(Sin(sprite.data[7], 8));
      }

      HandleSetAffineData(sprite, 256, 256, -(sprite.data[7]) << 8);
      TryFlipX(sprite);
}

/** static void Anim_VibrateToCorners(struct Sprite *sprite) */
export function Anim_VibrateToCorners(sprite: any): any {
  TryFlipX(sprite);
      if (sprite.data[2] > 40)
      {
          sprite.callback = WaitAnimEnd;
          sprite.x2 = 0;
      }
      else
      {
          let sign: any = null;
          if (!(sprite.data[2] & 1))
              sign = 1;
          else
              sign = -1;

          if ((sprite.data[2] % 4) / 2 == 0)
          {
              sprite.x2 = Sin((sprite.data[2] * 128 / 40) % 256, 16) * sign;
              sprite.y2 = -(sprite.x2);
          }
          else
          {
              sprite.x2 = -(Sin((sprite.data[2] * 128 / 40) % 256, 16)) * sign;
              sprite.y2 = sprite.x2;
          }
      }

      sprite.data[2]++;
      TryFlipX(sprite);
}

/** static void Anim_GrowInStages(struct Sprite *sprite) */
export function Anim_GrowInStages(sprite: any): any {
  TryFlipX(sprite);
      if (sprite.data[2] == 0)
      {
          HandleStartAffineAnim(sprite);
          sprite.data[5] = 0;
          sprite.data[6] = 0;
          sprite.data[7] = 0;
          sprite.data[2]++;
      }

      if (sprite.data[6] > 0)
      {
          sprite.data[6]--;
          if (sprite.data[5] != 3)
          {
              let scale: any = (8 * sprite.data[6]) / 20;
              scale = Sin(sprite.data[7] - scale, 64);
              HandleSetAffineData(sprite, 256 - scale, 256 - scale, 0);
          }
      }
      else
      {
          let _var: any = null;

          if (sprite.data[5] == 3)
          {
              if (sprite.data[7] > 63)
              {
                  sprite.data[7] = 64;
                  HandleSetAffineData(sprite, 256, 256, 0);
                  ResetSpriteAfterAnim(sprite);
                  sprite.callback = WaitAnimEnd;
              }
              _var = Cos(sprite.data[7], 64);
          }
          else
          {
              _var = Sin(sprite.data[7], 64);
              if (sprite.data[7] > 63)
              {
                  sprite.data[5] = 3;
                  sprite.data[6] = 10;
                  sprite.data[7] = 0;
              }
              else
              {
                  if (_var > 48 && sprite.data[5] == 1)
                  {
                      sprite.data[5] = 2;
                      sprite.data[6] = 20;
                  }
                  else if (_var > 16 && sprite.data[5] == 0)
                  {
                      sprite.data[5] = 1;
                      sprite.data[6] = 20;
                  }
              }
          }

          sprite.data[7] += 2;
          HandleSetAffineData(sprite, 256 - _var, 256 - _var, 0);
      }

      TryFlipX(sprite);
}

