          sprite.x2 = Sin(sprite.data[7] % 256, sprite.data[4]);
          sprite.data[7] += sprite.data[6];
          xScale = Sin(sprite.data[7] % 128, 96);
          HandleSetAffineData(sprite, 256 + xScale, 256, 0);
