/** static void Anim_RapidHorizontalHops(struct Sprite *sprite) */
export function Anim_RapidHorizontalHops(sprite: any): any {
  TryFlipX(sprite);
      if (sprite.data[2] > 2048)
      {
          sprite.callback = WaitAnimEnd;
          sprite.data[6] = 0;
      }
      else
      {
          let caseVar: any = (sprite.data[2] / 512) % 4;
          switch (caseVar)
          {
          case 0:
              sprite.x2 = -(sprite.data[2] % 512 * 16) / 512;
              break;
          case 1:
              sprite.x2 = (sprite.data[2] % 512 / 32) - 16;
              break;
          case 2:
              sprite.x2 = (sprite.data[2] % 512) / 32;
              break;
          case 3:
              sprite.x2 = -(sprite.data[2] % 512 * 16) / 512 + 16;
              break;
          }

          sprite.y2 = -(Sin(sprite.data[2] % 128, 4));
          sprite.data[2] += 24;
      }

      TryFlipX(sprite);
}

/** static void Anim_FourPetal(struct Sprite *sprite) */
export function Anim_FourPetal(sprite: any): any {
  TryFlipX(sprite);
      if (sprite.data[2] == 0)
      {
          sprite.data[6] = 0;
          sprite.data[7] = 64;
          sprite.data[2]++;
      }

      sprite.data[7] += 8;
      if (sprite.data[6] == 4)
      {
          if (sprite.data[7] > 63)
          {
              sprite.data[7] = 0;
              sprite.data[6]++;
          }
      }
      else
      {
          if (sprite.data[7] > 127)
          {
              sprite.data[7] = 0;
              sprite.data[6]++;
          }
      }

      switch (sprite.data[6])
      {
      case 1:
          sprite.x2 = -(Cos(sprite.data[7], 8));
          sprite.y2 = Sin(sprite.data[7], 8) - 8;
          break;
      case 2:
          sprite.x2 = Sin(sprite.data[7] + 128, 8) + 8;
          sprite.y2 = -(Cos(sprite.data[7], 8));
          break;
      case 3:
          sprite.x2 = Cos(sprite.data[7], 8);
          sprite.y2 = Sin(sprite.data[7] + 128, 8) + 8;
          break;
      case 0:
      case 4:
          sprite.x2 = Sin(sprite.data[7], 8) - 8;
          sprite.y2 = Cos(sprite.data[7], 8);
          break;
      default:
          sprite.x2 = 0;
          sprite.y2 = 0;
          sprite.callback = WaitAnimEnd;
          break;
      }

      TryFlipX(sprite);
}

