/** static void JoltRight(struct Sprite *sprite) */
export function JoltRight(sprite: any): any {
  TryFlipX(sprite);
      sprite.x2 -= sprite.data[2];
      if (sprite.x2 <= -sprite.data[6])
      {
          sprite.x2 = -sprite.data[6];
          sprite.data[7] = 2;
          sprite.callback = JoltRight_0;
      }

      TryFlipX(sprite);
}

